-- ============================================================
-- МИГРАЦИЯ 1: Система дилемм
-- ============================================================

CREATE TABLE dilemmas (
  id serial PRIMARY KEY,
  topic text NOT NULL,
  order_index integer NOT NULL,
  title text NOT NULL,
  scenario_text text NOT NULL,
  option_a text NOT NULL,
  option_b text NOT NULL,
  option_c text,
  consequence_a text NOT NULL,
  consequence_b text NOT NULL,
  consequence_c text,
  UNIQUE(topic, order_index)
);

CREATE TABLE dilemma_progress (
  telegram_id text NOT NULL,
  topic text NOT NULL,
  completed_count integer NOT NULL DEFAULT 0,
  pending_checkpoints integer NOT NULL DEFAULT 0,
  PRIMARY KEY (telegram_id, topic)
);

-- sessions теперь используются и для рекламы-чекпоинта дилемм, не только
-- для обычных роликов за монеты — общий кулдаун и антифрод для обоих
ALTER TABLE sessions ADD COLUMN session_type text NOT NULL DEFAULT 'video';
ALTER TABLE sessions ADD COLUMN dilemma_topic text;

-- ============================================================
-- МИГРАЦИЯ 2: Публичное подтверждение выплат (требование Adsgram, п.8)
-- ============================================================

CREATE TABLE public_payouts (
  id serial PRIMARY KEY,
  masked_id text NOT NULL,
  amount integer NOT NULL,
  paid_at timestamptz NOT NULL DEFAULT now()
);

-- Триггер: при переводе заявки на вывод в статус 'paid' — добавляем
-- запись в публичный список (обезличенно, без реального telegram_id)
CREATE OR REPLACE FUNCTION handle_public_payout_record()
RETURNS trigger
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
begin
  if new.status = 'paid' and old.status <> 'paid' then
    insert into public_payouts (masked_id, amount, paid_at)
    values (
      '●●●' || right(new.telegram_id, 4),
      new.amount,
      now()
    );
  end if;
  return new;
end;
$$;

CREATE TRIGGER trg_public_payout_record
AFTER UPDATE ON withdrawal_requests
FOR EACH ROW
EXECUTE FUNCTION handle_public_payout_record();

-- ============================================================
-- КОНТЕНТ: 20 дилемм, темы "work" и "money" (по 10 каждая)
-- ============================================================

INSERT INTO dilemmas (topic, order_index, title, scenario_text, option_a, option_b, option_c, consequence_a, consequence_b, consequence_c) VALUES
('work', 1, 'Чужая ошибка', 'Коллега случайно отправил клиенту неверный отчёт с завышенными цифрами. Клиент ещё не заметил. Коллега просит тебя промолчать.', 'Промолчать, это не моя ошибка', 'Сообщить руководителю', 'Тихо предупредить коллегу исправить самому', 'Клиент находит ошибку через месяц — репутация компании страдает, но тебя это формально не касается.', 'Коллега разочарован, но ошибку быстро исправляют. Тебе доверяют чуть больше.', 'Коллега благодарен, ошибку тихо исправляют. Но если всплывёт — вопросы будут и к тебе.'),
('work', 2, 'Переработка', 'Начальник просит остаться сверхурочно без оплаты «ради командного духа». Все остальные уже согласились.', 'Согласиться, чтобы не выделяться', 'Отказаться и уйти вовремя', 'Предложить компромисс: остаться на час, не больше', 'Ты устаёшь, но заслуживаешь одобрение начальства. В следующий раз попросят снова.', 'Коллеги смотрят косо первое время, но постепенно уважают твою границу.', 'Начальник немного недоволен, но принимает — прецедент здоровой границы установлен.'),
('work', 3, 'Повышение через голову', 'Тебе предлагают повышение, но на место твоего друга, который претендовал на ту же позицию дольше тебя.', 'Принять предложение', 'Отказаться в пользу друга', 'Принять, но предложить компенсацию другу', 'Карьера растёт, но дружба заметно охладевает.', 'Друг благодарен, но ты упускаешь возможность — неизвестно, повторится ли она.', 'Сложный разговор, но большинство ценят твою попытку сохранить и то, и другое.'),
('work', 4, 'Резюме', 'В резюме указали навык, которым ты владеешь лишь поверхностно. Собеседование прошло, тебя взяли на позицию, где этот навык критичен.', 'Разобраться на месте, никому не говорить', 'Честно предупредить руководителя в первый день', 'Попросить дополнительное обучение', 'Первые недели тяжёлые, но справляешься. Риск раскрытия остаётся.', 'Руководитель ценит честность, даёт время на адаптацию.', 'Компания вкладывается в тебя — доверие растёт, но есть ожидания быстрого результата.'),
('work', 5, 'Идея коллеги', 'На встрече ты предлагаешь идею как свою — на самом деле её подсказал коллега в неформальном разговоре накануне.', 'Оставить как есть', 'Признать авторство коллеги при всех', 'Поблагодарить коллегу лично после встречи', 'Идею хвалят, коллега узнаёт правду позже — доверие подорвано надолго.', 'Момент неловкий, но коллега получает заслуженное признание.', 'Публично никто не узнал, но между вами двумя — честность сохранена.'),
('work', 6, 'Собеседование друга', 'Тебя просят провести собеседование знакомого на открытую вакансию. Он явно слабее других кандидатов.', 'Порекомендовать его несмотря ни на что', 'Честно указать на его слабые стороны в отчёте', 'Дать шанс на испытательный срок', 'Знакомый получает работу, но команда может пострадать от нехватки навыков.', 'Знакомый не получает позицию, отношения могут испортиться.', 'Компромисс даёт шанс проявить себя без лишнего риска для команды.'),
('work', 7, 'Больничный', 'Ты не болен, но очень устал и хочешь взять больничный, чтобы отдохнуть — формально это будет обманом.', 'Взять больничный', 'Взять обычный отпуск за свой счёт', 'Прийти на работу через силу', 'Отдыхаешь, но чувство вины немного портит отдых.', 'Честно, но менее выгодно финансово.', 'Работаешь на пределе, качество работы страдает.'),
('work', 8, 'Утечка информации', 'Ты случайно узнал о готовящихся сокращениях раньше остальных. Близкий коллега может попасть под удар.', 'Промолчать, это конфиденциально', 'Предупредить коллегу неофициально', 'Анонимно намекнуть в общем чате', 'Коллега узнаёт в последний момент, шанса подготовиться не было.', 'Коллега благодарен, но ты рискуешь доверием руководства, если узнают источник.', 'Слух расходится быстро, но источник размывается — риск для тебя меньше.'),
('work', 9, 'Клиент манипулирует', 'Клиент угрожает уйти к конкурентам, если не получит условия, нарушающие внутренние правила компании.', 'Пойти навстречу клиенту', 'Твёрдо отказать, сославшись на правила', 'Эскалировать вопрос руководству', 'Клиент доволен, но создаётся прецедент для остальных.', 'Клиент может уйти, но правила остаются едиными для всех.', 'Решение снимается с тебя, но процесс занимает время.'),
('work', 10, 'Подсиживание', 'Ты замечаешь, что новый сотрудник методично старается выставить тебя в плохом свете перед начальством.', 'Прямо поговорить с ним', 'Игнорировать и просто работать лучше', 'Пожаловаться начальству на его поведение', 'Разговор может прояснить ситуацию или обостриться.', 'Медленный, но надёжный способ — результаты говорят сами за себя.', 'Риск выглядеть мнительным, если доказательств мало.'),
('money', 1, 'Найденный кошелёк', 'На улице находишь кошелёк с крупной суммой денег и документами владельца.', 'Оставить деньги себе, документы выбросить', 'Вернуть всё владельцу по документам', 'Сдать в полицию, не связываясь с владельцем напрямую', 'Быстрая выгода, но чувство вины преследует ещё долго.', 'Владелец безмерно благодарен, возможно даже вознаграждение.', 'Формально правильно, но занимает время, вознаграждения не будет.'),
('money', 2, 'Долг другу', 'Друг занял крупную сумму год назад, до сих пор не вернул и не упоминает об этом. Тебе сейчас очень нужны деньги.', 'Прямо напомнить и попросить вернуть', 'Молчать и ждать, пока сам вспомнит', 'Намекнуть через общих знакомых', 'Неловко, но вопрос решается — деньги возвращаются или отношения проясняются.', 'Деньги, скорее всего, не вернутся, обида копится.', 'Друг узнаёт окольным путём, может обидеться на способ, а не на просьбу.'),
('money', 3, 'Скидка по ошибке', 'В магазине кассир по ошибке пробивает товар в 10 раз дешевле реальной цены и не замечает этого.', 'Промолчать и уйти', 'Указать на ошибку', 'Заплатить полную цену наличными без объяснений', 'Экономия, но если заметят по камерам — вопросы будут именно к тебе.', 'Кассир благодарен, ошибку избегают в отчётности.', 'Кассир удивлён, но доволен — простое решение без неловкости.'),
('money', 4, 'Инвестиция друга', 'Друг предлагает вложиться в его новый бизнес, обещая быструю прибыль. Ты сомневаешься в его расчётах, но не хочешь его обидеть.', 'Вложиться, чтобы поддержать', 'Отказаться и честно объяснить причины', 'Вложить меньшую символическую сумму', 'Деньги либо удвоятся, либо будут потеряны — риск полностью на тебе.', 'Друг разочарован в моменте, но со временем ценит честность.', 'Компромисс — риск меньше, но и поддержка выглядит половинчатой.'),
('money', 5, 'Чаевые', 'Официант обслуживал плохо — забыл заказ, был грубоват. Но ты знаешь, что у него недавно проблемы в семье.', 'Не оставлять чаевые', 'Оставить обычные чаевые несмотря ни на что', 'Оставить чаевые и сказать пару добрых слов', 'Официант понимает намёк, но день и без того тяжёлый становится хуже.', 'Формально честно, но эмоционально не облегчает его день.', 'Мелочь, но иногда меняет настроение человека сильнее, чем кажется.'),
('money', 6, 'Займ родителям', 'Родители просят крупную сумму в долг «на неопределённый срок». У тебя как раз отложено на давнюю мечту.', 'Дать без вопросов', 'Отказать, объяснив свои планы', 'Дать меньшую сумму как разовую помощь', 'Мечта откладывается, но семья спокойна.', 'Возможна обида, но твои планы не рушатся.', 'Компромисс, который частично устраивает всех.'),
('money', 7, 'Подработка втайне', 'У тебя есть возможность подрабатывать в свободное время, но по контракту с основной работой это формально запрещено.', 'Подрабатывать втайне', 'Официально спросить разрешения', 'Отказаться от подработки', 'Доп. доход, но риск увольнения при раскрытии.', 'Могут отказать, но репутация останется чистой.', 'Надёжно, но упущенная возможность.'),
('money', 8, 'Совместная покупка', 'Вы с другом скидывались на подарок общему знакомому. Ты потратил больше времени на выбор и доставку — друг этого не замечает.', 'Промолчать', 'Мягко упомянуть о своём вкладе', 'Попросить компенсацию за доставку', 'Внутреннее недовольство копится незаметно для друга.', 'Друг, скорее всего, оценит и в следующий раз разделит труд по-другому.', 'Прямо, но может показаться мелочным по поводу небольшой суммы.'),
('money', 9, 'Наследство', 'Дальний родственник оставил небольшое наследство, но по факту должен был получить его другой, более близкий родственник — по ошибке в старом завещании.', 'Принять, как написано в документе', 'Добровольно передать по справедливости', 'Разделить пополам', 'Юридически всё чисто, но родственные отношения могут испортиться.', 'Формально теряешь деньги, но сохраняешь отношения в семье.', 'Компромисс, который редко устраивает обе стороны полностью.'),
('money', 10, 'Цена по ошибке онлайн', 'В интернет-магазине из-за технического сбоя дорогой товар продаётся почти бесплатно. Многие уже скупают партиями.', 'Заказать по ошибочной цене', 'Написать в магазин о технической ошибке', 'Заказать одну штуку для себя, не для перепродажи', 'Магазин, скорее всего, отменит заказы позже, если заметит масштаб.', 'Магазин благодарен, но выгоды ты не получаешь.', 'Небольшая личная выгода без участия в масштабной скупке.');
